@@ -198,241 +198,276 @@ fn job_to_run_blocking(target: &str) -> Result<JobToRun> {
     // Review cr-jl3b-1: a path is a job file; a bare word is a saved job,
     // whatever files the current folder holds.
     let job = if job_record::names_a_path(target) {
         let bytes = std::fs::read(target).with_context(|| format!("reading {target}"))?;
         job_record::read_job_file(&bytes).with_context(|| format!("reading {target}"))?
     } else if job_record::valid_job_name(target) {
         saved.load(target).map_err(|error| {
             let hint = if Path::new(target).is_file() {
                 format!(" (to run the file {target}, give it as a path: ./{target})")
             } else {
                 String::new()
             };
             eyre::eyre!("{error}{hint}")
         })?
     } else {
         eyre::bail!("{target} is not a saved job's name; give a job file as a path (./{target})");
     };
     check_machine(&config_dir, &job.spec)?;
     let (args, list) = spec_args(&config_dir, &job.spec)?;
     Ok(JobToRun {
         verb: job.spec.verb.clone(),
         args,
         origin: RunOrigin {
             saved_job: job.name.clone(),
             parent: None,
         },
         _list: list,
     })
 }

 /// `blit jobs retry <job-id|file>` (JOB_LOGS jl-4): a run's failed files
 /// sent again, as a new run — that run's next attempt, its parent
 /// recorded — on the machine the job belongs to. `None`, said, when the
 /// run failed nothing. Refused while the run goes on (here, or on the
 /// daemon a `--detach` run went on), and when its failures are not all
 /// known by name.
 ///
 /// A copy's or a mirror's retry is a copy of exactly the failed files,
 /// through the retry passes' own `retry_only` set: a mirror's deletions
 /// ran in its first run, and a mirror limited to a few files could delete
 /// the rest under `--delete-scope all`. A move's retry is the move again:
 /// its compare re-sends only what did not land, and its source is removed
 /// only once everything has — sending only the failed files and then
 /// removing the source would lose whatever changed there since.
 pub(crate) async fn job_to_retry(target: &str) -> Result<Option<JobToRun>> {
     let (config_dir, runs, _) = local_stores()?;
     // Review cr-jl3b-1: a path is a job file, a bare word a run ID.
     let (spec, record) = if job_record::names_a_path(target) {
         let bytes = std::fs::read(target).with_context(|| format!("reading {target}"))?;
         let file =
             job_record::read_job_file(&bytes).with_context(|| format!("reading {target}"))?;
         let run = file.run.ok_or_else(|| {
             eyre::eyre!("{target} holds a job but no run of it to retry; `blit jobs run` runs it")
         })?;
         // A run in a file that waited on its daemon: ask it now.
         let run = match job_record::ask_daemon(&run).await {
             Ok(DaemonAnswer::Ended(ended)) => *ended,
             _ => run,
         };
         (file.spec, run)
     } else {
         local_run(&runs, target)
             .await?
             .ok_or_else(|| no_such_run(target))?
     };
     check_machine(&config_dir, &spec)?;
     match &record.state {
         RunState::Running => eyre::bail!(
             "job {} is still running; retry it once it has ended",
             record.run_id
         ),
         RunState::Waiting { daemon, job_id } => eyre::bail!(
             "job {} went on on {daemon} as job {job_id}, and how it ended is not known \
              yet; retry it once `blit jobs list` shows it ended",
             record.run_id
         ),
         RunState::Finished | RunState::Interrupted => {}
     }
     if record.files_failed == 0 && record.failures.is_empty() {
         println!("Job {} failed no files; nothing to retry.", record.run_id);
         return Ok(None);
     }
     let (mut args, list) = spec_args(&config_dir, &spec)?;
     let verb = if spec.verb == "move" {
         "move"
     } else {
         let (failed, logged_left) = failed_identities(&config_dir, &record)?;
         // Review cr-jl4-1: under `--ignore-existing`, a path whose failed
         // write left this run's own incomplete copy is retried with the
         // flag off — the copy is not one the person asked to keep — as the
         // in-command retry passes do; the rest with it on.
         if spec.options.ignore_existing {
             if record.left_in_place_truncated {
                 eyre::bail!(
                     "job {} ran with --ignore-existing, and which of its failed files left \
                      their own incomplete copy at the destination is not all known; a retry \
                      could skip those copies as files to keep, so it is not made",
                     record.run_id
                 );
             }
-            let (own, own_raw) = retry_names(failed.iter().filter(|(path, raw)| {
-                is_left_in_place(&record, &logged_left, path, raw.as_deref())
-            }));
+            let own_leftovers = own_leftovers(&record, &failed, &logged_left)?;
+            let (own, own_raw) = retry_names(own_leftovers.iter());
             if !own.is_empty() || !own_raw.is_empty() {
                 args.retry_left_in_place = Some(own);
                 args.retry_left_in_place_raw = Some(own_raw);
             }
         }
         let (names, raw_names) = retry_names(failed.iter());
         args.retry_only = Some(names);
         args.retry_only_raw = Some(raw_names);
         "copy"
     };
     Ok(Some(JobToRun {
         verb: verb.to_string(),
         args,
         origin: RunOrigin {
             saved_job: record.saved_job.clone(),
             parent: Some((record.run_id.clone(), record.attempt)),
         },
         _list: list,
     }))
 }

 /// Whether a failed file's write left the run's own incomplete copy at the
 /// destination, by the file's identity — its text, or its bytes when its
 /// name is not UTF-8 (review cr-jl4fix2-1: two names of one text never
 /// share the status): the record's lists, or what this machine's log said.
 fn is_left_in_place(
     record: &RunRecord,
     logged: &HashSet<(String, Option<String>)>,
     path: &str,
     raw: Option<&str>,
 ) -> bool {
     let in_record = match raw {
         Some(raw) => record.left_in_place_raw.iter().any(|left| left == raw),
         None => record.left_in_place.iter().any(|left| left == path),
     };
     in_record || logged.contains(&(path.to_string(), raw.map(str::to_string)))
 }

+/// The failed files that left the run's own incomplete copy, by identity.
+/// Review cr-jl4fix3-1: a record from before its lists kept identities
+/// filed a raw-named file under its text, so from such a record a
+/// raw-named failure whose text is in the text list is ambiguous — its own
+/// leftover, or a UTF-8 sibling's — and is taken as the run's own only when
+/// this machine's log names that exact identity; otherwise the retry is
+/// refused, as when the list is not whole.
+fn own_leftovers(
+    record: &RunRecord,
+    failed: &HashSet<(String, Option<String>)>,
+    logged: &HashSet<(String, Option<String>)>,
+) -> Result<HashSet<(String, Option<String>)>> {
+    let mut own = HashSet::new();
+    for identity in failed {
+        let (path, raw) = identity;
+        if is_left_in_place(record, logged, path, raw.as_deref()) {
+            own.insert(identity.clone());
+            continue;
+        }
+        let ambiguous = !record.left_in_place_exact
+            && raw.is_some()
+            && record.left_in_place.iter().any(|left| left == path);
+        if ambiguous {
+            eyre::bail!(
+                "job {} ran with --ignore-existing, and its record (from an earlier blit) \
+                 cannot say whether the failed file {} left its own incomplete copy at \
+                 the destination; a retry could skip that copy as a file to keep, so it is \
+                 not made",
+                record.run_id,
+                job_log::shown_name(path, raw.as_deref())
+            );
+        }
+    }
+    Ok(own)
+}
+
 /// Every file a run failed, by its text and bytes: its record's, completed
 /// from this machine's log of the run when the record's list was cut
 /// short — with, from the log's whole reasons, the texts of those whose
 /// failed write left the run's own incomplete copy. An error when they are
 /// still not all known — a retry would leave the rest.
 fn failed_identities(
     config_dir: &Path,
     record: &RunRecord,
 ) -> Result<(
     HashSet<(String, Option<String>)>,
     HashSet<(String, Option<String>)>,
 )> {
     use crate::transfers::retry::UNRETRIED_PATH;
     let mut known: HashSet<(String, Option<String>)> = record
         .failures
         .iter()
         .filter(|failure| failure.path != UNRETRIED_PATH)
         .map(|failure| (failure.path.clone(), failure.raw.clone()))
         .collect();
     let short = |known: &HashSet<(String, Option<String>)>| {
         record.failures_truncated
             || record
                 .failures
                 .iter()
                 .any(|failure| failure.path == UNRETRIED_PATH)
             || (known.len() as u64) < record.files_failed
     };
     let mut left_in_place: HashSet<(String, Option<String>)> = HashSet::new();
     if short(&known) {
         // Review cr-jl4-3: the run's terminal state, read from its log in
         // order — a file that failed, and was not landed by a later pass —
         // not every failure the run ever met.
         let logs = config_dir.join("jobs").join("logs");
         for log in job_log::logs_for_run(&logs, &record.run_id, None).unwrap_or_default() {
             let Ok(lines) = job_log::open_log(&log.path) else {
                 continue;
             };
             let mut still_failed: HashSet<(String, Option<String>)> = HashSet::new();
             for line in lines.flatten() {
                 let LogLine::Event(event) = line else {
                     continue;
                 };
                 match event.body {
                     job_log::EventBody::FileFailed { path, raw, reason } => {
                         if reason
                             .contains(blit_core::remote::transfer::sink::INCOMPLETE_LEFT_IN_PLACE)
                         {
                             left_in_place.insert((path.clone(), raw.clone()));
                         }
                         still_failed.insert((path, raw));
                     }
                     job_log::EventBody::FileCopied { path, raw, .. }
                     | job_log::EventBody::FileSent { path, raw } => {
                         let identity = (path, raw);
                         left_in_place.remove(&identity);
                         still_failed.remove(&identity);
                     }
                     _ => {}
                 }
             }
             known.extend(still_failed);
         }
         if (known.len() as u64) < record.files_failed {
             eyre::bail!(
                 "job {} names only {} of the {} files it failed, so a retry would leave the \
                  rest; run the whole job again instead (`blit jobs save {} <name>`, then \
                  `blit jobs run <name>`)",
                 record.run_id,
                 known.len(),
                 record.files_failed,
                 record.run_id
             );
         }
     }
     Ok((known, left_in_place))
 }

 /// A retry's names (reviews cr-jl4-2, cr-jl4fix1-2): each failed file by
 /// its text, or — a name that is not UTF-8, whose text names no file — by
 /// its exact bytes, kept as bytes whatever this host is, so they reach a
 /// remote source as they are; only the host that enumerates them turns them
 /// into its paths. Bytes the record cannot give back fall to the text.
