  538: /// Write `value` to `path` whole: a temp file beside it, synced, then
  539: /// renamed over it.
  540: ///
  541: /// Review cr-jl3a-2: each write stages in a file of its own — two writers
  542: /// of one document (two `blit jobs` commands settling the same run) never
  543: /// share one — and the folder is synced after the rename, so the new
  544: /// document survives a crash.
  545: pub fn write_document(path: &Path, value: &impl Serialize) -> io::Result<()> {
  546:     let name = path.file_name().ok_or_else(|| {
  547:         io::Error::new(
  548:             io::ErrorKind::InvalidInput,
  549:             format!("{} names no file", path.display()),
  550:         )
  551:     })?;
  552:     let dir = path
  553:         .parent()
  554:         .filter(|dir| !dir.as_os_str().is_empty())
  555:         .unwrap_or(Path::new("."));
  556:     let mut staged = std::ffi::OsString::from(".");
  557:     staged.push(name);
  558:     staged.push(format!(".{}{TEMP_SUFFIX}", crate::job_log::new_run_id()?));
  559:     let temp = dir.join(staged);
  560:     let result = (|| {
  561:         let mut file = OpenOptions::new()
  562:             .write(true)
  563:             .create_new(true)
  564:             .open(&temp)?;
  565:         serde_json::to_writer_pretty(&mut file, value)?;
  566:         file.write_all(b"\n")?;
  567:         crate::job_log::sync_all(&file)?;
  568:         drop(file);
  569:         fs::rename(&temp, path)?;
  570:         crate::job_log::sync_dir(dir);
  590:     _lock: File,
  591:     lock_path: PathBuf,
  592: }
