  621:     /// Record a run starting: its spec, written once, and its record,
  622:     /// `running`, under the run's lock, held until the returned
  623:     /// [`LiveRun`] drops.
  624:     pub fn begin(&self, spec: &JobSpec, record: &RunRecord) -> io::Result<LiveRun> {
  625:         if !crate::job_log::valid_id(&record.run_id) {
  626:             return Err(io::Error::new(
  627:                 io::ErrorKind::InvalidInput,
  628:                 format!("{:?} cannot name a run", record.run_id),
  629:             ));
  630:         }
  631:         fs::create_dir_all(&self.dir)?;
  632:         let lock_path = self.path(&record.run_id, LOCK_SUFFIX);
  633:         let lock = open_lock(&lock_path)?;
  634:         lock.try_lock().map_err(|error| match error {
  635:             fs::TryLockError::WouldBlock => io::Error::new(
  636:                 io::ErrorKind::AlreadyExists,
  637:                 format!("run {} is already going", record.run_id),
  638:             ),
  639:             fs::TryLockError::Error(error) => error,
  640:         })?;
  641:         let live = LiveRun {
  642:             _lock: lock,
  643:             lock_path,
  644:         };
  645:         write_document(&self.path(&record.run_id, SPEC_SUFFIX), spec)?;
  646:         write_document(&self.path(&record.run_id, RECORD_SUFFIX), record)?;
  647:         Ok(live)
  648:     }
