  668:     /// `record` as it stands: a `running` record whose command has died
  669:     /// (its lock is free) becomes `interrupted`, on disk too.
  670:     fn settled(&self, mut record: RunRecord) -> RunRecord {
  671:         if record.state != RunState::Running {
  672:             return record;
  673:         }
  674:         let lock_path = self.path(&record.run_id, LOCK_SUFFIX);
  675:         let Ok(lock) = open_lock(&lock_path) else {
  676:             return record;
  677:         };
  678:         if lock.try_lock().is_err() {
  679:             // Its command is going.
  680:             return record;
  681:         }
  682:         // Re-read under the lock: the command may have finished between.
  683:         if let Ok(now) =
  684:             fs::read(self.path(&record.run_id, RECORD_SUFFIX)).and_then(|bytes| read_record(&bytes))
  685:         {
  686:             record = now;
  687:         }
  688:         if record.state == RunState::Running {
  689:             record.state = RunState::Interrupted;
  690:             record.outcome.get_or_insert(Outcome::Interrupted);
  691:             record
  692:                 .detail
  693:                 .get_or_insert_with(|| "its command stopped before the run ended".into());
  694:             if let Err(error) = self.update(&record) {
  695:                 log::warn!(
  696:                     "job records: could not mark run {} interrupted: {error}",
  697:                     record.run_id
  698:                 );
  699:             }
  700:         }
  701:         drop(lock);
  702:         let _ = fs::remove_file(&lock_path);
  703:         record
  704:     }
