355:             continue;
356:         }
357:         let ambiguous = !record.left_in_place_exact
358:             && raw.is_some()
359:             && record.left_in_place.iter().any(|left| left == path);
360:         if ambiguous {
361:             eyre::bail!(
362:                 "job {} ran with --ignore-existing, and its record (from an earlier blit) \
363:                  cannot say whether the failed file {} left its own incomplete copy at \
364:                  the destination; a retry could skip that copy as a file to keep, so it is \
365:                  not made",
366:                 record.run_id,
367:                 job_log::shown_name(path, raw.as_deref())
368:             );
369:         }
370:     }
371:     Ok(own)
