374: /// Every file a run failed, by its text and bytes: its record's, completed
375: /// from this machine's log of the run when the record's list was cut
376: /// short — with, from the log's whole reasons, the texts of those whose
377: /// failed write left the run's own incomplete copy. An error when they are
378: /// still not all known — a retry would leave the rest.
379: fn failed_identities(
380:     config_dir: &Path,
381:     record: &RunRecord,
382: ) -> Result<(
383:     HashSet<(String, Option<String>)>,
384:     HashSet<(String, Option<String>)>,
385: )> {
386:     use crate::transfers::retry::UNRETRIED_PATH;
387:     let mut known: HashSet<(String, Option<String>)> = record
388:         .failures
389:         .iter()
390:         .filter(|failure| failure.path != UNRETRIED_PATH)
391:         .map(|failure| (failure.path.clone(), failure.raw.clone()))
392:         .collect();
393:     let short = |known: &HashSet<(String, Option<String>)>| {
394:         record.failures_truncated
395:             || record
396:                 .failures
397:                 .iter()
398:                 .any(|failure| failure.path == UNRETRIED_PATH)
399:             || (known.len() as u64) < record.files_failed
400:     };
401:     let mut left_in_place: HashSet<(String, Option<String>)> = HashSet::new();
402:     if short(&known) {
403:         // Review cr-jl4-3: the run's terminal state, read from its log in
404:         // order — a file that failed, and was not landed by a later pass —
405:         // not every failure the run ever met.
406:         let logs = config_dir.join("jobs").join("logs");
407:         for log in job_log::logs_for_run(&logs, &record.run_id, None).unwrap_or_default() {
408:             let Ok(lines) = job_log::open_log(&log.path) else {
409:                 continue;
410:             };
411:             let mut still_failed: HashSet<(String, Option<String>)> = HashSet::new();
412:             for line in lines.flatten() {
413:                 let LogLine::Event(event) = line else {
414:                     continue;
415:                 };
416:                 match event.body {
417:                     job_log::EventBody::FileFailed { path, raw, reason } => {
418:                         if reason
419:                             .contains(blit_core::remote::transfer::sink::INCOMPLETE_LEFT_IN_PLACE)
420:                         {
421:                             left_in_place.insert((path.clone(), raw.clone()));
422:                         }
423:                         still_failed.insert((path, raw));
424:                     }
425:                     job_log::EventBody::FileCopied { path, raw, .. }
426:                     | job_log::EventBody::FileSent { path, raw } => {
427:                         let identity = (path, raw);
428:                         left_in_place.remove(&identity);
429:                         still_failed.remove(&identity);
430:                     }
431:                     _ => {}
432:                 }
433:             }
434:             known.extend(still_failed);
435:         }
436:         if (known.len() as u64) < record.files_failed {
437:             eyre::bail!(
438:                 "job {} names only {} of the {} files it failed, so a retry would leave the \
439:                  rest; run the whole job again instead (`blit jobs save {} <name>`, then \
440:                  `blit jobs run <name>`)",
441:                 record.run_id,
442:                 known.len(),
443:                 record.files_failed,
444:                 record.run_id
445:             );
446:         }
447:     }
