500: /// that format and a version this build reads, then parsed whole as that
501: /// version. The version is read first, untyped, so a newer document's
502: /// fields are never forced into this version's shape.
503: fn read_versioned<T: for<'de> Deserialize<'de>>(bytes: &[u8], format: &str) -> io::Result<T> {
504:     use serde_json::Value;
505:     let invalid = |message: String| io::Error::new(io::ErrorKind::InvalidData, message);
506:     let Ok(Value::Object(head)) = serde_json::from_slice::<Value>(bytes) else {
507:         return Err(invalid(format!("not a {format} document")));
508:     };
509:     let named = head.get("format").and_then(Value::as_str).unwrap_or("");
510:     if named != format {
511:         return Err(invalid(format!(
512:             "not a {format} document (format {named:?})"
513:         )));
514:     }
515:     match head.get("version").and_then(Value::as_u64) {
516:         Some(1) => serde_json::from_slice(bytes)
517:             .map_err(|error| invalid(format!("a damaged {format} document: {error}"))),
518:         Some(v) if v > u64::from(VERSION) => Err(invalid(format!(
519:             "written by a newer blit ({format} version {v}; this one reads up to {VERSION})"
520:         ))),
521:         Some(v) => Err(invalid(format!(
522:             "{format} version {v}, which no blit writes"
523:         ))),
524:         None => Err(invalid(format!("a {format} document without a version"))),
525:     }
526: }
